void dei_feature_save( void )
{
	nvfs_wr( nvfs_feat_dei , &dei_feature_list );	
}

void dei_feature_save_sleep(Wake_Status wake_status)
{
	if(wake_status == s_SLEEP)
		dei_feature_save();
}

